// nisargadatta_te.dart
// Nisargadatta maharaj quotes and articles (Malyalam)

import '../articlesquotes.dart';

final nisargadattaSaint = Saint(
  'nisargadatta',
  'നിസർഗദത്ത മഹാരാജ്',
  'assets/images/nisargadatta.jpg',
  [
    'നിങ്ങൾ നിങ്ങളെ എങ്ങനെ കാണുന്നു എന്നതിൽ നിങ്ങൾ അല്ല. നിങ്ങൾ ആരെന്നു കണ്ടെത്തുക.',
    'യാഥാർത്ഥ്യം മരിക്കുകയില്ല, അസത്യത്തിൽ ജീവിച്ചിരുന്നില്ല.',
    'ജ്ഞാനം എന്നെ ഒന്നുമല്ല എന്ന് പറയുന്നു. പ്രേമം എന്നെ എല്ലാം ആണെന്ന് പറയുന്നു. ഈ രണ്ടിന്റെ ഇടയിൽ എന്റെ ജീവിതം ഒഴുകുന്നു.',
    'നിങ്ങൾ പരമാത്മാവാണ്. ചെറിയ മനസ്സ് വെക്കേണ്ട.',
    'നിങ്ങൾ ആരാണെന്ന് അറിയാൻ, നിങ്ങൾ ആദ്യം നിങ്ങൾ ആരല്ലെന്ന് അന്വേഷിച്ച് അറിയണം.',
    'നിനക്കുള്ള ബോധവും എനിക്ക് ഉള്ള ബോധവും, ദൃശ്യമായ രണ്ട്, ഒന്നാണ്, ഐക്യം തേടുക, അതാണ് പ്രേമം.',
    'നിങ്ങളുടെ സ്വഭാവത്തെ നിർവചിക്കാനുള്ള പ്രവണതയെ ഒഴിവാക്കാൻ നിങ്ങൾക്ക് വേണ്ടത് എല്ലാം ആണ്.',
    'ഒരു നേരം നിങ്ങൾക്ക് ഈ വഴിയാണ് ലക്ഷ്യം എന്ന് മനസ്സിലായാൽ, നിങ്ങൾ എപ്പോഴും ഈ വഴിയിൽ തന്നെയാണ്, ലക്ഷ്യം നേടാൻ അല്ല, മറിച്ച് അതിന്റെ സൌന്ദര്യംയും ജ്ഞാനവും ആസ്വദിക്കാൻ, ജീവിതം ഒരു ജോലി ആവാൻ നിർത്തുകയും സ്വാഭാവികവും ലളിതവുമായതാക്കുകയും ചെയ്യും.',
    'നിങ്ങൾ ശരീരം അല്ല. നിങ്ങൾ മനസ്സ് പോലും അല്ല. നിങ്ങൾ ഇരുവരും പ്രത്യക്ഷപ്പെടുന്ന ബോധമാണ്.',
    'നിങ്ങളുടെ യാഥാർത്ഥികമായ സത്തയെ നിങ്ങൾ അറിയുന്ന നിമിഷം, നിങ്ങൾക്ക് ഒന്നും ഭയപ്പെടേണ്ടതില്ല.',
    'നിങ്ങൾ ഈ അല്ലെങ്കിൽ ആ ചെയ്യുന്നതായി സ്വപ്നം കാണുന്നത് നിർത്തുക, നിങ്ങൾ എല്ലാത്തിനും ഉറവിടവും ഹൃദയവുമാണ് എന്നത് നിങ്ങളുടെ മനസ്സിൽ തെളിയും.',
    'നിങ്ങൾ അനുഭവിക്കുന്ന ഒന്നും നിങ്ങളുടെ സ്വന്തം അല്ല. നിങ്ങൾ അനുഭവിക്കുന്ന ഒന്നും നിങ്ങളുടെ കൂടെയുണ്ടായിട്ടുള്ളതുമായ ബന്ധമില്ല.',
    'എല്ലാ പരമ്പരാഗത മാനദണ്ഡങ്ങളും തള്ളുക. അവയെ പരമ്പരയുടെ അനുകൂലികളായവർക്കു വിട്ടുകൂടുക.',
    'നിന്റെ സത്യമായ വീട് ശൂന്യത്തിൽ, എല്ലാ ഉള്ളടക്കത്തിന്റെ ശൂന്യതയിൽ ആണ്.',
    'ഞാൻ അകത്ത് നോക്കുമ്പോൾ ഞാൻ ഒന്നുമല്ല എന്ന് കാണുന്നത് ജ്ഞാനം ആണ്. ഞാൻ പുറത്തു നോക്കുമ്പോൾ ഞാൻ എല്ലാം ആണെന്ന് കാണുന്നത് പ്രേമമാണ്.',
    'മനസ്സാണ് ആഴം സൃഷ്ടിക്കുന്നത്, ഹൃദയം അതിനെ കടക്കുന്നു.',
    'നിങ്ങൾ എന്താണെന്ന് നിങ്ങൾ കരുതുന്നുവോ, അതല്ല നിങ്ങൾ.',
    'നിങ്ങൾ നിങ്ങളെ ഒരു വ്യക്തിയായി കരുതുന്നു, എന്നാൽ നിങ്ങൾ ഒരിക്കലും ഒരു വ്യക്തിയായി ജനിച്ചിട്ടില്ല.',
    'നിങ്ങൾ യാഥാർത്ഥ്യത്തിൽ ഒരു വസ്തുവല്ല, മറ്റ് വസ്തുക്കളിൽ നിന്ന് വേർപെടുത്തപ്പെട്ടതുമല്ല.',
    'വാസ്തവത്തെ തേടുന്നത് എല്ലാ ശ്രമങ്ങളിലെയും ഏറ്റവും അപകടകരമായതാണ്, കാരണം ഇത് നിങ്ങള്‍ ജീവിക്കുന്ന ലോകത്തെ നശിപ്പിക്കുന്നു.',
    'എല്ലാ വേർപാട്, എല്ലാ തരത്തിലുള്ള അകലം, അന്യത്വം എല്ലാം അസത്യമാണ്.',
    'നിങ്ങൾ ആകുന്നു ആ സമഗ്രമായ ബോധത്തിന്റെ പ്രതിഫലനവും പ്രകടനവും ആയ അന്തിമ സാധ്യത.',
    'വ്യക്തിഗതമായതിനെ സംരക്ഷണം ആവശ്യമാണ്, യാഥാർത്ഥ്യം സംരക്ഷണം ആവശ്യപ്പെടുന്നില്ല.',
    'നിന്റെ സ്വന്തം കല്‍പ്പനയല്ലാതെ നിന്നെ കഷ്ടപ്പെടുത്താൻ ഒന്നുമില്ല.',
    'ഒരു കാര്യത്തിൽ നിശ്ചയമായും അറിയുമ്പോൾ, നിങ്ങളുടെ സ്വന്തം കற்பനകൾ dışında നിങ്ങളെ കഷ്ടപ്പെടുത്താൻ മറ്റൊന്നും ഇല്ല എന്ന്, നിങ്ങൾ നിങ്ങളുടെ ആഗ്രഹങ്ങളും ഭയങ്ങളും അവഗണിക്കാൻ തുടങ്ങുന്നു.',
    'നിങ്ങൾ ലോകത്തിൽ അല്ല, ലോകം നിങ്ങളിൽ ആണ്.',
    '\'ഞാൻ ആകുന്നു\' എന്ന അനുഭവം നിങ്ങളുടെ സ്വന്തംതാണ്. നിങ്ങൾ അതിനെ വിട്ടുപോകാൻ കഴിയില്ല, എന്നാൽ നിങ്ങൾ അത് ഏതെങ്കിലും കാര്യത്തിലേക്ക് കൈമാറാൻ കഴിയും, ഉദാഹരണത്തിന് \'ഞാൻ യുവൻ\', \'ഞാൻ സമ്പന്നൻ\' തുടങ്ങിയവയിൽ.',
    'വേദനയും ആനന്ദവും തമ്മിലുള്ള തീരങ്ങളിൽ ജീവിതത്തിന്റെ നദി ഒഴുകുന്നു. മനസ്സ് ജീവിതത്തോടൊപ്പം ഒഴുകാൻ നിരസിക്കുമ്പോൾ, തീരങ്ങളിൽ കുടുങ്ങുമ്പോൾ മാത്രമാണ് അത് ഒരു പ്രശ്നമാകുന്നത്.',
    'അറിയപ്പെടുന്നതിൽ നിന്നുള്ള സ്വാതന്ത്ര്യം.',
    'നിന്റെ ദുർബലത, നീ ഈ ലോകത്തിൽ ജനിച്ചുവെന്ന വിശ്വാസത്തിലാണുള്ളത്.',
    'നിന്റെ മോക്ഷത്തിനായി മനസിനെ ആശ്രയിക്കരുത്. നിനക്കു അടിമത്തത്തിലേക്ക് കൊണ്ടുവന്നത് മനസാണ്.',
    'യാഥാർത്ഥിക ഗുരുവാണ് ജീവിതം തന്നെ.',
    'നിനക്ക് അതിനെ നേടേണ്ടതില്ല, കാരണം നീ തന്നെ അതാണ്.',
    'പ്രേമം പറയുന്നു \'ഞാൻ എല്ലാം\'. ജ്ഞാനം പറയുന്നു \'ഞാൻ ഒന്നുമില്ല\'. ഇരുവരുടെയും ഇടയിൽ, എന്റെ ജീവിതം ഒഴുകുന്നു.',
    'മൂന്നായ്മ: മനസ്സ്, ആത്മാവ്, ആത്മാവ്, പരിശോധിക്കുമ്പോൾ, ഏകതയിലേക്ക് മാറുന്നു.',
    'സാധാരണയായി ഇരിക്കൂ. നിങ്ങളുടെ യഥാർത്ഥ സ്വഭാവം പുറത്തുവരാൻ അനുവദിക്കൂ. അന്വേഷിക്കുന്നതിലൂടെ നിങ്ങളുടെ മനസിനെ കുഴപ്പിക്കേണ്ട.',
    'നിന്റെ സ്വന്തം ആത്മാവ് ആണ് നിന്റെ അന്തിമ ഗുരു. പുറം ഗുരു വെറും ഒരു മൈൽസ്റ്റോൺ മാത്രമാണ്.',
    'നിന്റെ ലോകത്ത് എല്ലാം ഒരു ആരംഭവും ഒരു അവസാനവും ഉണ്ടായിരിക്കണം. അതുണ്ടായില്ലെങ്കിൽ, നീ അതിനെ അനന്തം എന്ന് വിളിക്കുന്നു.',
    'അനുഭവിച്ച മനുഷ്യൻ ലോകത്തെ അതിന്റെ യാഥാർത്ഥ്യത്തിൽ കാണുന്നു: ആകൃതിയിൽ വ്യത്യാസമുള്ള, എന്നാൽ സ്വഭാവത്തിൽ ഒന്ന്.',
    'കല്പനയില്ലാതെ കാണാൻ, വഞ്ചനയില്ലാതെ കേൾക്കാൻ പഠിക്കുക.',
    'മനസാണ് നിങ്ങളെ മനസിന്റെ ഉള്ളതിനെ കുറിച്ച് അറിയിക്കുന്നത്. വഞ്ചിതരാകല്ല.',
    'സത്യമാണ് നല്ല പെരുമാറ്റത്തിനുള്ള പ്രതിഫലം അല്ല, അല്ലെങ്കിൽ ചില പരീക്ഷകൾ വിജയിച്ചാൽ ലഭിക്കുന്ന സമ്മാനം.',
    'നിങ്ങളെ മനുഷ്യനാണെന്ന് ചിന്തിപ്പിക്കുന്നത് മനുഷ്യൻ അല്ല.',
    'നിങ്ങൾ സ്വയം ഒരു തടവുകെട്ടാൻ വളരെ അധികം ഊർജ്ജം ചെലവഴിച്ചിട്ടുണ്ട്. ഇപ്പോൾ അതിനെ തകർക്കാൻ അത്രയും സമയം ചെലവഴിക്കുക.',
    'നിങ്ങൾ ആ വ്യക്തി അല്ലെന്ന് മനസ്സിലാക്കാൻ, ആ വ്യക്തിയെ കാണുക. ആ വ്യക്തിയെ ബോധത്തിലെ ഒരു വസ്തുവായി നോക്കുക.',
    'ശരീരം-മനസ്സ് തിരിച്ചറിഞ്ഞു വിട്ടുവിടുന്നതിൽ എന്താണ് ബുദ്ധിമുട്ട്? നിങ്ങള്‍ ശരീരം-മനസ്സ് അല്ലല്ലോ.',
    'നിങ്ങൾ മരണത്തെക്കുറിച്ച് ഭയപ്പെടുന്നത് നിങ്ങൾ സ്വയം അറിയാത്തതിനാൽ ആണ്. യഥാർത്ഥ നിങ്ങൾ മരണമില്ലാത്തവനാണ്.',
    'നിങ്ങളെ എല്ലായിടത്തും, എല്ലാത്തിനും മീതെ അറിയുന്നതിൽ തടയുന്നത് ഓർമ്മയുടെ അടിസ്ഥാനത്തിൽ ഉള്ള മനസ്സാണ്.',
    'മനസ്സ് സമയത്തിൽ ഉണ്ട്, നാം സമയത്തെ അതിക്രമിക്കുന്നു.',
    'നിങ്ങൾ ഭയപ്പെടുന്നില്ലെങ്കിൽ, നിങ്ങൾ തന്നെ പ്രണയം ആണ്.',
    'നിങ്ങൾ നിങ്ങളെ എങ്ങനെ കാണുന്നത് ആകുന്നില്ല. നിങ്ങൾ ശരീരം അല്ല, മനസ്സും അല്ല, വ്യക്തിയെന്ന അനുഭവവും അല്ല. നിങ്ങൾ എല്ലാ ഈ അവസ്ഥകൾ പ്രത്യക്ഷപ്പെടുകയും അദൃശ്യമായും ആകുന്ന timeless awareness ആണ്.',
    'നിങ്ങൾ നിങ്ങളുടെ ആത്മാവിനെ വ്യക്തിയായി അല്ലാതെ ബോധമായി അറിയുന്ന നിമിഷം, എല്ലാ ദു:ഖവും അവസാനിക്കുന്നു. ശേഷിക്കുന്നത് അനുഭവമല്ല, നിങ്ങളുടെ സ്വാഭാവിക അവസ്ഥയായ സമാധാനമാണ്.',
    'ശരീരം ഉണ്ടാകുന്നതിന് മുമ്പ്, ലോകം പ്രത്യക്ഷമായതിന് മുമ്പ്, നീ ഉണ്ടായിരുന്നു. എല്ലാ ആശയങ്ങളിലേക്കും പോകുന്നതിന് മുമ്പുള്ള ആ അനുഭവത്തിൽ തുടരുക, മറ്റൊന്നും വിട്ടുകളയുക.',
    '\'ഞാൻ\' എന്നത് ആദ്യത്തെ വാതിലാണ്. അതിൽ സ്ഥിരമായി ഇരിക്കുക. \'ഞാൻ\' പോലും ലയിക്കുമ്പോൾ, പരമതത്വം നിലനിൽക്കുന്നു.',
    'നിങ്ങൾ ലോകത്തിൽ ഇല്ല; ലോകം നിങ്ങളുടെ ഉള്ളിൽ ആണ്. നിങ്ങൾ നിങ്ങളുടെ ബോധത്തിൽ മുഴുവൻ ബ്രഹ്മാണ്ഡം കയറ്റുന്നു.',
    'നിങ്ങൾ എന്താണെന്ന് അറിയാൻ, നിങ്ങൾ ആദ്യം നിങ്ങൾ അല്ലാത്തതിനെ അന്വേഷിക്കണം. കാണപ്പെടുന്ന, അനുഭവപ്പെടുന്ന, അല്ലെങ്കിൽ അനുഭവിച്ചുകൊണ്ടിരിക്കുന്ന ഏതെങ്കിലും കാര്യം നിങ്ങൾ അല്ല.',
    'സത്യമായ ആത്മാവ് നേടേണ്ടതല്ല. നിങ്ങൾക്കുള്ള എല്ലാ തെറ്റായ ആശയങ്ങൾ ഉപേക്ഷിച്ചപ്പോൾ നിങ്ങൾ ആകുന്നവയാണ് അത്.',
    'നിങ്ങൾ നിങ്ങളെ പരിധിയുള്ളവനായി കണക്കാക്കുന്നു, അതിനാൽ ആ പരിധിയ yüzം നിങ്ങൾക്കു ദു:ഖം നൽകുന്നു. യാഥാർത്ഥ്യത്തിൽ, നിങ്ങൾ ആകുന്ന കാര്യങ്ങൾക്ക് ഒരു പരിധിയുമില്ല.',
    'ശരീരം-മനസുമായി തിരിച്ചറിയുന്നത് നിർത്തുമ്പോൾ, നിങ്ങൾ ഒരിക്കലും ബന്ധിതനല്ലെന്ന്, ഒരിക്കലും പ്രശ്നത്തിലല്ലെന്ന്, ഒരിക്കലും അപൂർണനല്ലെന്ന് നിങ്ങൾ കണ്ടെത്തുന്നു.',
    'അവബോധം വ്യക്തിഗതമല്ല. വ്യക്തി അവബോധത്തിൽ പ്രത്യക്ഷപ്പെടുന്നു, എന്നാൽ അവബോധം വ്യക്തിക്ക് ആകർഷിതമല്ല.',
    'ചിന്തനശക്തി തന്നെ ഒരു താത്കാലികാവസ്ഥയാണ്. ഇത് പ്രത്യക്ഷപ്പെടുകയും അപ്രത്യക്ഷപ്പെടുകയും ചെയ്യുന്നു. ചിന്തനശക്തിയെ അറിയുന്നത് അതിന്റെ അതീതമാണ്.',
    'അബ്സല്യൂട്ട് തന്റെ സ്വയംബോധത്തിൽ അല്ല. ബോധം അബ്സല്യൂട്ടിൽ ഉദ്ഭവിക്കുന്ന ഒരു പ്രതിഭാസമാണ്, സമുദ്രത്തിലെ ഒരു തരംഗം പോലെ.',
    'നിങ്ങൾ ബോധത്തെ നിങ്ങളുടെ സ്വരൂപം എന്ന് കരുതുന്നു, പക്ഷേ ബോധം പോലും നിരീക്ഷിക്കപ്പെടുന്നു. ബോധത്തെ അറിയുന്ന അവസ്ഥയെ കണ്ടെത്തുക.',
    'ശരീരംയും ലോകവും ബോധത്തോടുകൂടി ഉത്ഭവിക്കുന്നു. ബോധം ഇല്ലാത്തപ്പോൾ, ലോകവും ഇല്ല.',
    'ചിന്തനത്തിന് മുമ്പ്, അനുഭവം ഇല്ല, സമയം ഇല്ല, സ്ഥലം ഇല്ല — എന്നാൽ നീ ഉണ്ട്. അത് നിന്റെ സത്യ സ്വഭാവമാണ്.',
    'ചിന്തനശക്തി ശരീരത്തെ ആശ്രയിക്കുന്നു, എന്നാൽ പരമതത്വം ഒന്നിനും ആശ്രയിച്ചിട്ടില്ല. വ്യത്യാസം അറിയുക.',
    'മരണത്തിൽ ബോധം ലയിക്കുമ്പോൾ, നിങ്ങൾ യഥാർത്ഥത്തിൽ ആരാണെന്ന് മരിക്കുന്നില്ല, കാരണം അത് ഒരിക്കലും ജനിച്ചിട്ടില്ല.',
    'അവകാശം പറയാൻ കഴിയുന്നില്ല. പറയാൻ കഴിയുന്ന എന്തും വെറും ബോധത്തെക്കുറിച്ചാണ്.',
    'ചിന്തനത്തിന്റെ ഉറവിടത്തിൽ നിൽക്കുക, നിങ്ങൾ അതിനെ അതിജീവിക്കും.',
    'നിങ്ങൾ ബോധത്തിന്റെ ചലനത്തെ യാഥാർത്ഥ്യമായി തെറ്റിദ്ധരിക്കുന്നു. യാഥാർത്ഥ്യം ചലിക്കുന്നതല്ലാത്തതാണ്.',
    'നിന്റെ ഏക സാധന \'ഞാൻ ആകുന്നു\' എന്ന അനുഭവത്തെ പിടിച്ചുനിന്ന്, മറ്റൊന്നും ആത്മമല്ല എന്ന നിലയിൽ തള്ളുകയാണ്.',
    'എന്ത് പ്രത്യക്ഷപ്പെടുന്നുവെന്ന് മാറ്റാൻ ശ്രമിക്കേണ്ട. നീ എന്താണെന്ന് മാത്രം മനസ്സിലാക്കുക, എല്ലാം സ്വയം മാറും.',
    'ശ്രമം ആവശ്യമുണ്ട്, ശ്രമരഹിതത്വം കണ്ടെത്തുന്നത് വരെ. പിന്നീട്, ശ്രമം പോലും വിട്ടുകളയുന്നു.',
    'സ്വയം അന്വേഷണം മാനസിക വ്യായാമമല്ല. ഇത് പ്രത്യക്ഷപ്പെടുന്ന ഏതെങ്കിലും കാര്യവുമായി തിരിച്ചറിയാൻ സ്ഥിരമായ നിരസനമാണ്.',
    'നിങ്ങളുടെ ചിന്തകൾ ആകാശത്തിൽ കടന്നുപോകുന്ന മേഘങ്ങളെ കാണുന്നതുപോലെ ശ്രദ്ധിക്കുക. അവയെ നിങ്ങളുടെതെന്നു അവകാശപ്പെടരുത്.',
    'മനസ്സ് മനസ്സിനെ അതിജീവിക്കാൻ സഹായിക്കില്ല. അതിനെ മനസ്സിലാക്കുന്നതിലൂടെ നിങ്ങൾ അതിനപ്പുറം പോകണം.',
    'നിങ്ങൾ മനസ്സിനെ നിരീക്ഷിക്കുമ്പോൾ, നിങ്ങൾ ഇതിനകം അതിനപ്പുറം ആകുന്നു.',
    'എത്ര നേരം എടുക്കുമെന്ന് ചോദിക്കേണ്ട. നിങ്ങളുടെ അന്വേഷണത്തിൽ സത്യസന്ധവും സത്യവാങ്മൂലവുമായിരിക്കണം.',
    'നിങ്ങൾക്ക് മനസിനെ ശുദ്ധീകരിക്കാൻ ആവശ്യമില്ല. അതുമായി തിരിച്ചറിവ് നിർത്തുക.',
    'മൗനം ശബ്ദത്തിന്റെ അഭാവം അല്ല; അത് തിരിച്ചറിയലിന്റെ അഭാവമാണ്.',
    'മനുഷ്യൻ ഓർമ്മകൾ, ശീലങ്ങൾ, കൂടിച്ചേർന്ന സാഹചര്യങ്ങൾ എന്നിവയുടെ സമാഹാരമാണ്. നീ ആ സമാഹാരമല്ല.',
    'ആത്മാവിന്റെ ഒരു വ്യത്യസ്തമായ ആശയമാണ് എഗോ — ബോധം സ്വീകരിച്ച ഒരു തെറ്റായ കേന്ദ്രം.',
    'നിങ്ങൾ \'ഞാൻ ദു:ഖിക്കുന്നു\' എന്ന് പറയുമ്പോൾ, ഈ \'ഞാൻ\' ആരാണ് എന്ന് അന്വേഷിക്കുക. നിങ്ങൾ അതിനെ കണ്ടെത്തുകയില്ല.',
    '\'ഞാൻ ചെയ്യുന്നവനാണ്\' എന്ന ആശയം ബന്ധനമാണ്. അത് പോയാൽ, സ്വാതന്ത്ര്യം ഉണ്ടാകും.',
    'സ്വഭാവം യാഥാർത്ഥ്യമല്ല; അത് ബോധം ധരിക്കുന്ന ഒരു മുഖക്കവചമാണ്.',
    'നിങ്ങൾ നിങ്ങളെ ഒരു വ്യക്തിയായി കരുതുന്നവരെ, നിങ്ങൾ ഭയത്തിൽ ജീവിക്കും.',
    'ശരീരത്തോടുകൂടി വ്യക്തിത്വത്തിന്റെ അനുഭവം ആരംഭിക്കുന്നു, അതോടുകൂടി അവസാനിക്കുന്നു.',
    'നിങ്ങൾ ശൂന്യതയെ ഭയപ്പെടുന്നതിനാൽ വ്യക്തിയോട് പിടിച്ചിരിക്കുന്നു, എന്നാൽ ആ ശൂന്യത സമാധാനമാണ്.',
    'ആ വ്യക്തി ലയിക്കുമ്പോൾ, ശേഷിക്കുന്നത് ശൂന്യമായല്ല, പൂർണമായാണ്.',
    'ആത്മാവ് തുടർച്ചയെ ആഗ്രഹിക്കുന്നു; യാഥാർത്ഥ്യത്തിന് അതില്ല.',
    'എല്ലാ ദു:ഖവും തിരിച്ചറിയലിൽ നിന്നാണ് ജനിക്കുന്നത്. നിങ്ങൾ താത്കാലികമായതിനെ നിങ്ങളുടെ സ്വഭാവമായി സ്വീകരിക്കുന്നതിനാൽ നിങ്ങൾ ദു:ഖിക്കുന്നു.',
    'ആഗ്രഹം അപൂർണ്ണതയുടെ അനുഭവത്തിൽ നിന്ന് ഉത്ഭവിക്കുന്നു, അത് തന്നെ അസത്യമാണ്.',
    'ഭയമുണ്ടാവുന്നത് വ്യക്തിക്കാണ്. ആത്മാവ് ഭയമറിയുന്നില്ല.',
    'നിങ്ങൾ ശരീരം അല്ല എന്ന് അറിയുമ്പോൾ, മരണത്തിന്റെ ഭയം നഷ്ടപ്പെടുന്നു.',
    'വേദന ശാരീരികമാണ്; ദു:ഖം മാനസികമാണ്. നിങ്ങൾ മനസ്സിലാക്കുന്നതിലൂടെ ദു:ഖത്തെ അതിജീവിക്കാം.',
    'നിങ്ങൾ എങ്ങനെ പ്രതിരോധിക്കുന്നു, അതു നിലനിൽക്കുന്നു. നിങ്ങൾ എങ്ങനെ മനസ്സിലാക്കുന്നു, അതു ലയിക്കുന്നു.',
    'ആഗ്രഹം ഭാവിയിൽ പ്രക്ഷിപ്തമായ ഒരു ഓർമ്മയാണ്.',
    'സ്വാതന്ത്ര്യം ആഗ്രഹത്തിന്റെ പൂർത്തീകരണം അല്ല, ആഗ്രഹത്തിൽനിന്നുള്ള സ്വാതന്ത്ര്യമാണ്.',
    'ദു:ഖം നിങ്ങള്‍ നിങ്ങളുടെ സ്വയം സംബന്ധിച്ച തെറ്റായ ധാരണയില്‍ ആണെന്ന് നിങ്ങള്‍ക്ക് അറിയിക്കുന്ന ഒരു സൂചനയാണ്.',
    'കള്ളമായ തിരിച്ചറിവ് അവസാനിക്കുമ്പോൾ, ദു:ഖവും അതോടൊപ്പം അവസാനിക്കുന്നു.',
    'ലോകം അസത്യമായിട്ടില്ല, എന്നാൽ നിങ്ങൾ അത് എങ്ങനെ കരുതുന്നുവെന്ന് അല്ല. ഇത് ബോധത്തിന്റെ ഒരു പ്രക്ഷിപ്തമാണ്.',
    'ലോകം യാഥാർത്ഥ്യമായിരിക്കുന്നു എന്ന് തോന്നുന്നത്, നിങ്ങൾ അതിന്റെ ഒരു ഭാഗമാണെന്ന് വിശ്വസിക്കുന്നതിനാൽ ആണ്.',
    'ജ്ഞാനം നിശ്ചലമായപ്പോൾ, ലോകം നിശ്ചലമാണ്.',
    'ബ्रह്മാണ്ഡം കാണപ്പെടുന്നവരായിരിക്കുമ്പോൾ മാത്രമാണ് നിലനിൽക്കുന്നത്.',
    'നിങ്ങൾ ലോകത്തിന് യാഥാർത്ഥ്യം നൽകുന്നത് അതിനെ വ്യക്തിപരമായി സ്വീകരിക്കുമ്പോഴാണ്.',
    'ലോകത്തിന് ബോധത്തെക്കാൾ സ്വതന്ത്രമായ ഒരു അസ്തിത്വം ഇല്ല.',
    'വാസ്തവം എളുപ്പമാണ്; ഭ്രാന്തം ജടിലമാണ്.',
    'ലോകം നല്ലതും മോശമായതും അല്ല. അത് നിങ്ങളുടെ മനസ്സിലാക്കലിന്റെ പ്രതിബിംബമാണ്.',
    'നിങ്ങൾ \'യാഥാർത്ഥ്യജീവിതം\' എന്നു വിളിക്കുന്നത് ഒരു അനുഭവങ്ങളുടെ പ്രവാഹമാണ്.',
    'ലോകം ഒരു നാടകമാണ്, എന്നാൽ ബോധം അതിനെ ഗൗരവത്തോടെ സ്വീകരിക്കുന്നു.',
    'ഗുരു നിങ്ങള്‍ക്ക് പുതിയതൊന്നും കൊടുക്കുന്നില്ല. അദ്ദേഹം തെറ്റായതെല്ലാം നീക്കം ചെയ്യുന്നു.',
    'കൃപ ഒരു സംഭവമല്ല; അത് നിങ്ങളുടെ സ്വഭാവമാണ്.',
    'നിങ്ങൾ തയ്യാറായപ്പോൾ, ഉപദേശം നിങ്ങളെ കണ്ടെത്തും.',
    'ഗുരു സൂചിപ്പിക്കുന്നു, പക്ഷേ നിങ്ങൾ കാണണം.',
    'നിങ്ങളുടെ സ്വയം സ്ഥിരീകരിക്കുന്നതുവരെ പഠനത്തിൽ വിശ്വാസം വയ്ക്കുക.',
    'ഗുരുവിൽ വിശ്വാസം നിങ്ങളുടെ സ്വന്തം ആത്മാവിൽ വിശ്വാസമാണ്.',
    'വാക്കുകൾ വെറും സൂചികകളാണ്. അവയ്ക്ക് പിടിച്ചുനിൽക്കരുത്.',
    'ഉയർന്ന ഉപദേശം ശാന്തിയാണ്.',
    'ഒരു സത്യമായ അധ്യാപകൻ ആത്മാവിനെ ആശ്വസിപ്പിക്കുന്നില്ല; അവൻ അതിനെ നശിപ്പിക്കുന്നു.',
    'അവബോധം പൂര്‍ത്തിയാകുമ്പോള്‍ ഗുരു അപ്രത്യക്ഷനാകുന്നു.',
    'മുക്തി സമയത്തിൽ ഒരു നേട്ടമല്ല. അത് കാലഹരണമില്ലാത്തതിന്റെ തിരിച്ചറിവാണ്.',
    'നിങ്ങൾ ഇപ്പോൾ സ്വതന്ത്രനാണ്, എന്നാൽ നിങ്ങൾ നിങ്ങളെ ബദ്ധമായവനായി കണക്കാക്കുന്നു.',
    'സ്വാതന്ത്ര്യം നിങ്ങൾ ഇഷ്ടപ്പെടുന്ന കാര്യങ്ങൾ ചെയ്യുന്നതല്ല, മറിച്ച് ആഗ്രഹം കൊണ്ട് ബദ്ധമായിരിക്കാതിരിക്കുക ആണ്.',
    'എപ്പോൾ \'ഞാൻ\' ഇല്ലാത്തപ്പോൾ, ബദ്ധതയുമില്ല.',
    'മുക്തി അന്വേഷണത്തിന്റെ അവസാനം ആണ്.',
    'മുക്തനായവനോടൊന്നും സംഭവിക്കില്ല, കാരണം സംഭവിക്കേണ്ടവനൊന്നുമില്ല.',
    'മുക്തമായ അവസ്ഥ സാധാരണ, സ്വാഭാവികവും, ശ്രദ്ധിക്കപ്പെടാത്തതുമാണ്.',
    'നിങ്ങൾ സ്വതന്ത്രരാകുന്നില്ല; നിങ്ങൾ ഒരിക്കലും ബദ്ധനല്ലെന്ന് നിങ്ങൾ കണ്ടെത്തുന്നു.',
    'ഉയർന്ന അവസ്ഥ ഒരു അവസ്ഥയുമല്ല.',
    'അജ്ഞാനം അവസാനിക്കുമ്പോൾ, പ്രത്യേകമായ ഒന്നും സംഭവിക്കില്ല — സത്യമാണ് വെളിപ്പെടുന്നത്.',
    'നിങ്ങൾ യാഥാർത്ഥ്യത്തിന്റെ ഒരു ഭാഗമല്ല. നിങ്ങൾ യാഥാർത്ഥ്യം തന്നെയാണ്.',
    'എന്തെങ്കിലും പ്രത്യക്ഷപ്പെടുന്നുവെങ്കിൽ അത് അപ്രത്യക്ഷപ്പെടണം. പ്രത്യക്ഷപ്പെടാത്തത് അപ്രത്യക്ഷപ്പെടാൻ കഴിയില്ല.',
    'അവസാനത്തിനെക്കുറിച്ചുള്ളത് ഒരു ഗുണമില്ല, എങ്കിലും എല്ലാ ഗുണങ്ങളും അതിൽ നിന്നാണ് ഉത്ഭവിക്കുന്നത്.',
    'നിങ്ങൾ ആബ്സല്യൂട്ട് ഒരു വസ്തുവായി അറിയാൻ കഴിയില്ല, കാരണം നിങ്ങൾ അതാണ്.',
    'ആത്മാവ് അനുഭവപ്പെടുന്നില്ല; അത് അനുഭവിക്കുന്നതാണു.',
    'എല്ലാ ചോദ്യങ്ങളും അവസാനിക്കുമ്പോൾ, സത്യം നിലനിൽക്കുന്നു.',
    'നിനക്കു ഒന്നും ചേർക്കേണ്ടതില്ല; വെറും തെറ്റായ ആശയങ്ങൾ മാത്രമാണ് നീക്കം ചെയ്യേണ്ടത്.',
    'നിങ്ങൾ യാഥാർത്ഥ്യത്തിൽ എന്താണ് എന്ന് സ്ഥിരീകരണത്തിനും നിഷേധത്തിനും മീതെ ആണ്.',
    'ശാന്തമായിരിക്കുക, കാണുക — ഇത്ര മാത്രം.',
    'സത്യത്തിന്റെ സ്വഭാവം ലളിതമാണ്, പക്ഷേ മനസ്സ് ലളിതത്വത്തെ എതിര്‍ക്കുന്നു.',
    'അവന്റെ അസ്തിത്വത്തിന്റെ അനുഭവത്തിൽ തുടരുക, ആ അനുഭവം പോലും ലയിക്കുമ്പോൾ വരെ.',
    'സത്യത്തെ പിടിക്കാൻ ശ്രമിക്കേണ്ട; അസത്യത്തെ വിട്ടുപോകാൻ അനുവദിക്കുക.',
    'അവബോധം ആണ് കീ, അനുഭവം അല്ല.',
    'എന്താണ് യാഥാർത്ഥ്യം എന്നും സദാ സാന്നിധ്യത്തിലാണ്.',
    'നിങ്ങൾ സമയത്തിനു മുമ്പാണ്.',
    'വാസ്തവത്തിൽ ഒന്നും തെറ്റില്ല; നിങ്ങളുടെ ആശയങ്ങൾ മാത്രമാണ് തെറ്റായത്.',
    'ശ്രമികൻ ഇല്ലാതാകുമ്പോൾ, അന്വേഷിതം വെളിപ്പെടുന്നു.',
    'അവബോധങ്ങളാൽ ശൂന്യമായിരിക്കുക.',
    'നിങ്ങൾ സാക്ഷിയാണ്, സാക്ഷ്യം കാണുന്നവൻ അല്ല.',
    'നിങ്ങൾ ആകുന്നു — അത് മതിയാകും.',
  ],
  [
    Article(
        heading: 'ഞാൻ ആരാണ്? - അടിസ്ഥാനപരമായ ചോദ്യം',
        body: 'നിസർഗദത്ത മഹാരാജിന്റെ ഉപദേശം "ഞാൻ ആരാണ്?" എന്ന അടിസ്ഥാന ചോദ്യത്തെ ചുറ്റിപ്പറ്റിയാണ്. അദ്ദേഹം തന്റെ ശിഷ്യരെ എല്ലാ ആശയങ്ങളും തിരിച്ചറിവുകളും മറികടന്ന് അവരുടെ യഥാർത്ഥ സ്വഭാവം അന്വേഷിക്കാൻ നിരന്തരം പ്രേരിപ്പിക്കുകയായിരുന്നു. \n\n"നിങ്ങൾ നിങ്ങളെ നിങ്ങൾ കരുതുന്നവരല്ല," അദ്ദേഹം പറയാറുണ്ടായിരുന്നു. "നിങ്ങൾ എന്താണെന്ന് കണ്ടെത്തുക." ഈ അന്വേഷണമാണ് ബുദ്ധിമുട്ടുള്ള ഒരു വ്യായാമം അല്ല, \'ഞാൻ\' അനുഭവത്തിന്റെ ഉറവിടത്തിലേക്ക് നേരിട്ടുള്ള അന്വേഷണമാണിത്.\n\nമഹാരാജ് നമ്മൾ ശരീരം, മനസ്സ്, ചിന്തകൾ, വികാരങ്ങൾ, ജീവിതത്തിൽ നാം വഹിക്കുന്ന വിവിധ വേഷങ്ങൾ എന്നിവയുമായി പതിവായി തിരിച്ചറിവ് ചെയ്യുന്നതായി പഠിപ്പിച്ചു. എന്നാൽ ഇവയൊക്കെ ബോധത്തിൽ പ്രത്യക്ഷപ്പെടുന്ന വസ്തുക്കളാണ്. നാം അവിടെ പ്രത്യക്ഷപ്പെടുന്ന സാക്ഷിത്വമാണ്, അവയുടെ വസ്തുക്കളല്ല.\\n\\nസ്വയം അന്വേഷിക്കുന്ന പ്രക്രിയയിൽ, നിങ്ങൾ അല്ലാത്തതെല്ലാം നിഷേധിക്കേണ്ടതാണ് - "ഞാൻ ശരീരം അല്ല, ഞാൻ മനസ്സ് അല്ല, ഞാൻ ചിന്തകൾ അല്ല" - നിങ്ങൾ എന്താണ് അവശേഷിക്കുന്നത് എന്നതിലേക്ക് എത്തുന്നതുവരെ. അവശേഷിക്കുന്നത് ശുദ്ധമായ ബോധം, ശുദ്ധമായ സത്ത, നിങ്ങളുടെ യഥാർത്ഥ സ്വഭാവമാണ്.\\n\\n"നിങ്ങൾ എന്താണെന്ന് അറിയാൻ, നിങ്ങൾ ആദ്യം നിങ്ങൾ അല്ലാത്തതെന്താണെന്ന് അന്വേഷിക്കുകയും അറിയുകയും ചെയ്യണം" എന്ന് മഹാരാജ് ഊന്നി പറഞ്ഞു. ഈ ഒഴിവാക്കലിന്റെ പ്രക്രിയ നിങ്ങളുടെ അടിസ്ഥാന സ്വഭാവത്തെ ശുദ്ധമായ സാക്ഷിത്വമായി തിരിച്ചറിയുന്നതിലേക്ക് നയിക്കുന്നു, എല്ലാ ഗുണങ്ങളും പരിധികളും മീതെ.\\n\\n"ഞാൻ ആരാണ്?" എന്ന ചോദ്യത്തെ ശക്തമായ ആത്മാർത്ഥതയും സത്യസന്ധതയും കൊണ്ട് പിന്തുടരേണ്ടതാണ്. ഇത് ബുദ്ധിമുട്ടിൽ മാത്രം മനസ്സിലാക്കുന്നത് മതിയല്ല; നിങ്ങളുടെ ആസ്തിത്വത്തിന്റെ ഓരോ നിമിഷത്തിലും പരന്ന ഒരു ജീവൻ അന്വേഷണമാകണം, അതുവരെ വ്യത്യസ്ത വ്യക്തിയെന്ന തെറ്റായ അനുഭവം മുഴുവനായും പിരിഞ്ഞു പോകണം.'
    ),
    Article(
        heading: 'ചേതനയുടെ സ്വഭാവം',
        body: 'നിസർഗദത്ത മഹാരാജിന്റെ ബോധത്തെ വിശദീകരിക്കുന്നതിൽ ഒരു പ്രത്യേക രീതിയുണ്ടായിരുന്നു, അത് ആഴത്തിലുള്ളതും ആക്സസിബിള്‍ ആണും. അദ്ദേഹം വ്യക്തിഗത ബോധം (അദ്ദേഹം "ഞാൻ ആകുന്നു" എന്ന അനുഭവം എന്ന് വിളിച്ചിരിക്കുന്നു) എന്നതും എല്ലാ അനുഭവങ്ങൾക്കപ്പുറം ഉള്ള പരമ ബോധം എന്നതും തമ്മിൽ വ്യത്യാസം വരുത്തി. \n\n"ഞാൻ ആകുന്നു" എന്നത് ബോധത്തിലെ ആദ്യ ചലനമാണ്, എല്ലാ അനുഭവങ്ങൾക്കും ജന്മം നൽകുന്ന പ്രാഥമിക ആശയമാണ്. മഹാരാജ്, "ഞാൻ ഈ" അല്ലെങ്കിൽ "ഞാൻ ആ" പോലുള്ള അധികങ്ങൾ ഇല്ലാതെ ഈ ശുദ്ധമായ "ഞാൻ ആകുന്നു" അനുഭവത്തെ പിടിച്ചിരിക്കാൻ നമ്മൾ ശ്രമിക്കണം എന്ന് പഠിപ്പിച്ചു.\n\n"നിന്റെ ബോധവും എന്റെ ബോധവും, പുറമേ രണ്ടായി കാണപ്പെടുന്ന, ഒരുതന്നെയാണ്" അദ്ദേഹം പറയുമായിരുന്നു. ഈ മനസ്സിലാക്കൽ വേർപാട് എന്ന ഭ്രമത്തെ ലയിപ്പിച്ച്, എല്ലാ പ്രത്യക്ഷ വൈവിധ്യങ്ങളുടെ അടിസ്ഥാനം ആയ ഐക്യത്തെ വെളിപ്പെടുത്തുന്നു.\n\nമഹാരാജ് ബോധം മസ്തിഷ്കം അല്ലെങ്കിൽ ശരീരം വഴി ഉത്പാദിപ്പിക്കപ്പെടുന്നില്ല എന്ന് വിശദീകരിച്ചു. ശരീരംയും മസ്തിഷ്കവും ബോധത്തിൽ പ്രത്യക്ഷപ്പെടുന്നു. ബോധം വ്യക്തിഗതമല്ല; ഇത് സർവവ്യാപിയായതാണ്, നമ്മൾ വ്യക്തിഗത ബോധമായി കരുതുന്നതു ഈ സർവവ്യാപിയായ ബോധത്തിന്റെ ഒരു പ്രതിഫലനമാണ്. \n\nഅവസാന യാഥാർത്ഥ്യം ബോധത്തെക്കാളും മുകളിലാണ് - ബോധം പ്രത്യക്ഷപ്പെടുകയും അപ്രത്യക്ഷപ്പെടുകയും ചെയ്യുന്ന അവസ്ഥയാണ് ഇത്. ബോധത്തിനുമുമ്പെയും, ഉൽപത്തി-അനുഉൽപത്തി മുമ്പെയും, ഇത് നിങ്ങളുടെ യഥാർത്ഥ സ്വഭാവമാണ്. \n\n"നിങ്ങൾ പരമ യാഥാർത്ഥ്യമാണ്," മഹാരാജ് പ്രഖ്യാപിക്കും. "ചെറിയ മനസ്സുള്ളവനാകരുത്." ഈ പരമ യാഥാർത്ഥ്യം ഒരു വസ്തുവായി അറിയാൻ കഴിയില്ല, കാരണം നിങ്ങൾ തന്നെ അതാണ്. നിങ്ങൾ ആരെന്നു നിങ്ങൾ കരുതുന്ന എല്ലാ കാര്യങ്ങളുടെ ലയനം വഴി മാത്രമേ ഇത് തിരിച്ചറിയാൻ കഴിയൂ.'
    ),
    Article(
        heading: 'വ്യക്തിയുടെ മായാ',
        body: 'നിസർഗദത്ത മഹാരാജിന്റെ ഏറ്റവും വിപ്ലവകരമായ ഉപദേശങ്ങളിൽ ഒന്നാണ് വ്യക്തിയുടെ ഭ്രമാത്മക സ്വഭാവത്തെക്കുറിച്ചുള്ളത്. അദ്ദേഹം പറയുന്നത്: "നിങ്ങൾ നിങ്ങളെ ഒരു വ്യക്തിയായി കരുതുന്നു, പക്ഷേ നിങ്ങൾ ഒരിക്കലും വ്യക്തിയായി ജനിച്ചിട്ടില്ല." \n\nവ്യക്തി എന്നത് സ്മരണകൾ, ചിന്തകൾ, തിരിച്ചറിവുകളുടെ ഒരു സമാഹാരമാണ്, ഇത് ഒരു പ്രത്യക്ഷ തുടർച്ച സൃഷ്ടിക്കുന്നു. എന്നാൽ അടുത്തു പരിശോധിക്കുമ്പോൾ, വ്യക്തി എന്നറിയപ്പെടുന്ന ഒരു ഉറച്ച ഘടകം ഇല്ല. ഇത് ഒരു സിനിമ പോലെയാണ് - വ്യക്തിഗത ഫ്രെയിമുകൾ ചലനവും കഥയും സൃഷ്ടിക്കുന്ന ഭ്രമം. \n\nമഹാരാജ് പഠിപ്പിച്ചത്, വ്യക്തി ഒരു മാനസിക നിർമ്മിതിയാണ്, സ്വതന്ത്ര യാഥാർത്ഥ്യമില്ലാത്ത ആശയങ്ങളുടെ ഒരു കൂട്ടമാണ്. "നിങ്ങൾ എന്താണ് എന്ന് നിങ്ങൾ കരുതുന്നുവോ, നിങ്ങൾ അതല്ല," അദ്ദേഹം ഉറപ്പിക്കുമായിരുന്നു. നിങ്ങളുടെ (ചിന്തനം) ഉള്ളിൽ വ്യക്തി പ്രത്യക്ഷപ്പെടുന്നു, പക്ഷേ നിങ്ങൾ വ്യക്തി അല്ല. \n\nഈ ബോധവൽക്കരണം മോചിതമാക്കുന്നതാണ്, കാരണം വ്യക്തിയുടെ എല്ലാ പ്രശ്നങ്ങളും, പരിമിതികളും, ദു:ഖങ്ങളും ഭ്രാന്തമായവയാണ്. നിങ്ങൾ വ്യക്തി അല്ലെന്ന് തിരിച്ചറിയുമ്പോൾ, നിങ്ങൾ വ്യക്തിയുടെ വിധി, karma, ആചാരങ്ങൾ എന്നിവയിൽ നിന്ന് മോചിതനാകുന്നു.\n\n"നിങ്ങൾ കാണുന്ന ഒന്നും നിങ്ങളുടെ സ്വന്തം അല്ല. നിങ്ങൾ കാണുന്ന ഒന്നും നിങ്ങളുമായി ബന്ധപ്പെട്ടിട്ടില്ല," മഹാരാജ് പറയുമായിരുന്നു. ഇതിൽ ശരീരം, മനസ്സ്, ചിന്തകൾ, ഞങ്ങൾ സാധാരണയായി നമ്മുടെതെന്ന് കരുതുന്ന വികാരങ്ങൾ ഉൾപ്പെടുന്നു.\n\nനിങ്ങൾ വ്യക്തി അല്ല എന്ന തിരിച്ചറിവ് ഒരു തത്ത്വചിന്താ നിലയല്ല, എന്നാൽ earnest self-inquiry വഴി ലഭിക്കുന്ന നേരിയ ബോധവൽക്കരണമാണ്. ഈ തിരിച്ചറിവ് സ്ഥിരവും അസ്ഥിരമല്ലാത്തതുമായപ്പോൾ, നിങ്ങൾ നിങ്ങളുടെ യഥാർത്ഥ സ്വഭാവമായുള്ളതിൽ - ശുദ്ധമായ ബോധം, ശുദ്ധമായ ആസ്തിത്വം, എല്ലാ വ്യക്തിഗത പരിധികളെയും മറികടന്ന നിലയിൽ നിൽക്കുന്നു.'
    ),
    Article(
        heading: 'പ്രേമവും ജ്ഞാനവും - സത്യത്തിന്റെ രണ്ട് ചിറകുകൾ',
        body: 'നിസർഗദത്ത മഹാരാജ് തന്റെ പ്രശസ്തമായ വാചകത്തിൽ സാക്ഷാത്കാരത്തിന്റെ പരadoxയെ മനോഹരമായി പ്രകടിപ്പിച്ചു: "ജ്ഞാനം എന്നെ ഒന്നുമല്ല എന്ന് പറയുന്നു. പ്രേമം എന്നെ എല്ലാം ആണെന്ന് പറയുന്നു. ഈ രണ്ടിനിടയിൽ എന്റെ ജീവിതം ഒഴുകുന്നു."\n\nജ്ഞാനം നിങ്ങളുടെ യഥാർത്ഥ സ്വഭാവമായ ശുദ്ധമായ ബോധത്തെ തിരിച്ചറിയലാണ്, അതിന് ഗുണങ്ങൾ, രൂപം, ഗുണങ്ങൾ ഇല്ല - മനസ്സാൽ പിടിക്കാൻ കഴിയുന്ന ഒന്നുമല്ല. ഈ ദൃശ്യം നിന്നെ ശൂന്യമായ, എല്ലാ അനുഭവങ്ങളും പ്രത്യക്ഷപ്പെടുന്ന ശൂന്യമായ സ്ഥലം ആകുന്നു.\n\nപ്രേമം, മറിച്ച്, ഈ തന്നെ ബോധം പ്രത്യക്ഷപ്പെടുന്ന എല്ലാം എന്നതിന്റെ അടിസ്ഥാനമായ തിരിച്ചറിയലാണ്. നിങ്ങൾ ഒന്നിൽ നിന്നും വേർപെടുത്തപ്പെട്ടിട്ടില്ല; നിങ്ങൾ പലതായുള്ള ഒരു പ്രത്യക്ഷമായവനാണ്. ഇത് നിങ്ങളുടെ സ്വന്തം ആത്മാവായി എല്ലാ സൃഷ്ടിയെയും ഉൾക്കൊള്ളുന്ന പ്രേമമാണ്.\n\nഇവ പരസ്പരം വിരുദ്ധമായ സത്യങ്ങൾ അല്ല, പക്ഷേ ഒരേ സാക്ഷാത്കാരത്തിന്റെ രണ്ട് വശങ്ങളാണ്. അവകാശം ശൂന്യവും സമ്പൂർണ്ണവും, ഒന്നും എല്ലാം, ഉന്നതവും ആന്തരികവുമാണ്. \n\n"ഞാൻ എന്റെ ഉള്ളിൽ നോക്കുമ്പോൾ ഞാൻ ഒന്നുമല്ല എന്ന് കാണുന്നത് ജ്ഞാനം ആണ്. ഞാൻ പുറത്തു നോക്കുമ്പോൾ ഞാൻ എല്ലാം ആണെന്ന് കാണുന്നത് പ്രേമമാണ്," മഹാരാജ് വിശദീകരിച്ചു. ഈ ഇരട്ട തിരിച്ചറിവ് സമ്പൂർണ്ണമായ മനസ്സിലാക്കലിന്റെ അടയാളമാണ്.\n\nഈ മനസ്സിലാക്കലിൽ നിന്ന് ജീവിക്കുന്നത്, നിങ്ങളെ ഒന്നുമല്ല (നോ-തിംഗ്) എന്നറിയുന്നതിന്റെ സമാധാനത്തിൽ സ്ഥാപിതമായിരിക്കുകയാണ്, അതേസമയം നിങ്ങളുടെ സ്വന്തം പ്രത്യക്ഷമായ എല്ലാം പ്രേമിക്കുന്നതും ആണ്. ഇത് സാക്ഷാത്കൃതനായ സത്യത്തിന്റെ സ്വാഭാവിക അവസ്ഥയാണ് - സ്വയം ശൂന്യമായെങ്കിലും എല്ലാംക്കുള്ള പ്രേമത്തിൽ സമ്പൂർണ്ണമായ.'
    ),
    Article(
        heading: 'ജന്മവും മരണമും അതിക്രമിച്ച്',
        body: 'നിസർഗദത്ത മഹാരാജിന്റെ മരണംയും അമരത്വവും സംബന്ധിച്ച ഉപദേശങ്ങൾ അത്യന്തം ശക്തവും ആശ്വസകരവുമായിരുന്നു. "യാഥാർത്ഥ്യം മരിക്കുകയില്ല, അസത്യമായത് ഒരിക്കലും ജീവിച്ചിരുന്നില്ല," അദ്ദേഹം ഉറപ്പോടെ പറയാറുണ്ടായിരുന്നു.\n\nഅദ്ദേഹത്തിന്റെ ദൃശ്യം പ്രകാരം, ജനനം മരണം എന്നു നമ്മൾ വിളിക്കുന്നതെല്ലാം ബോധത്തിൽ ഉള്ള പ്രത്യക്ഷതകൾ മാത്രമാണ്, ഒരു സ്വപ്നത്തിലെ ദൃശ്യങ്ങൾ പോലെയാണ്. ശരീരം ജനിക്കുന്നു, മരിക്കുന്നു, എന്നാൽ നിങ്ങൾ - ശരീരം പ്രത്യക്ഷപ്പെടുന്ന ബോധം - ഒരിക്കലും ജനിച്ചിട്ടില്ല, അതിനാൽ നിങ്ങൾ മരിക്കാനാവില്ല.\n\n"നിങ്ങൾ മരണമെക്കുറിച്ച് ഭയപ്പെടുന്നത് നിങ്ങൾ സ്വയം അറിയാത്തതിനാലാണ്," മഹാരാജ് സൂചിപ്പിക്കാറുണ്ടായിരുന്നു. "യഥാർത്ഥ നിങ്ങൾ മരണമില്ലാത്തവനാണ്." ഈ മരണമെന്ന ഭയം നാശവാനായ ശരീരവുമായി തിരിച്ചറിയുന്നതിൽ നിന്നാണ് വരുന്നത്, അമരമായ ബോധമായി നിങ്ങളെ തിരിച്ചറിയുന്നതിന് പകരം.\n\nമഹാരാജ് നമ്മൾ യാഥാർത്ഥത്തിൽ ജനനം അല്ലെങ്കിൽ മരണം അനുഭവിച്ചിട്ടില്ല എന്ന് പഠിപ്പിച്ചു. നമുക്ക് ഭാവത്തിന്റെ കാഴ്ചപ്പാടുകളും, ഭവനത്തിന്റെ ഓർമ്മകളും ഉണ്ട്, പക്ഷേ നമ്മുടെ യാഥാർത്ഥ്യമായ അനുഭവം എപ്പോഴും ഇപ്പോഴത്തെ ബോധത്തിന്റെ നിമിഷത്തിലാണ്. ഈ ബോധം എപ്പോഴും ഉണ്ടായിരിക്കുന്നു, എപ്പോഴും ഉണ്ടായിരിക്കും. \n\nനിന്റെ മരണമില്ലാത്ത സ്വഭാവത്തെ മനസ്സിലാക്കുന്നത് ഒരു വിശ്വാസമല്ല അല്ലെങ്കിൽ ആശ്വാസമല്ല, മറിച്ച് ഒരു നേരിട്ടുള്ള തിരിച്ചറിവാണ്. നീ നിന്റെ ശുദ്ധ ബോധമായി നന്നായി അറിയുമ്പോൾ, മരണം എന്നതിന്റെ ഭയം നശിക്കുന്നു, കാരണം നീ മരിക്കുന്ന ഒന്നും ഇല്ലെന്ന് നീ തിരിച്ചറിഞ്ഞിരിക്കുന്നു. \n\n"നിന്റെ ദുർബലത എനിക്ക് പറയുന്നത്, നീ ലോകത്തിൽ ജനിച്ചുവെന്ന വിശ്വാസമാണ്," അദ്ദേഹം പറയുമായിരുന്നു. യാഥാർത്ഥ്യത്തിൽ, ലോകം നിനക്കുള്ളിൽ പ്രത്യക്ഷപ്പെടുന്നു; നീ ലോകത്തിൽ പ്രത്യക്ഷപ്പെടുന്നില്ല. ഈ അടിസ്ഥാനപരമായ മനസ്സിലാക്കലിലെ മാറ്റം നിന്റെ ജീവിതത്തോടും മരണമോടും ഉള്ള മുഴുവൻ ബന്ധത്തെ മാറ്റുന്നു. \n\nഈ ഉപദേശത്തിന്റെ പ്രായോഗിക അർത്ഥം വലിയ സ്വാതന്ത്ര്യവും ഭയമില്ലായ്മയും ആണ്. നിങ്ങൾ മരണമില്ലാത്ത യാഥാർത്ഥ്യമായി നിങ്ങളെ അറിയുമ്പോൾ, നിങ്ങളുടെ സ്വാഭാവിക സന്തോഷവും സമാധാനവും മൃത്യുവിന്റെ നിഴലാൽ മൂടപ്പെടാതെ, നിങ്ങൾ മുഴുവൻ ജീവിക്കാനും പൂർണ്ണമായും സ്നേഹിക്കാനും കഴിയും.'
    ),
  ],
);
